<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { api } from '../api'
import type { InspectionConfig, InspectionMaterial } from '../types'
const config=ref<InspectionConfig|null>(null),revision=ref(''),itemIndex=ref(-1),materialIndex=ref(-1),loading=ref(true),saving=ref(false),error=ref(''),notice=ref('')
const controller=new AbortController()
const selected=computed(()=>config.value?.items[itemIndex.value] || null)
const material=computed(()=>selected.value?.materials[materialIndex.value] || null)
const cadence:Record<string,string>={annual:'年报',semiannual:'半年报',monthly:'月报',daily:'日报',weekly:'周报（暂按月取数）'}
const groups:Record<string,string>={prevention_daily:'防冲工作日报',dispatch_daily:'调度日报',analysis:'日分析记录',release:'生产组织通知',relief_acceptance:'钻孔验收',threshold:'预警临界指标',design:'防冲设计',workface_risk:'工作面评价',coal_risk:'煤层评价'}
async function load(){loading.value=true;error.value='';try{const r=await api.config(controller.signal);config.value=r.config;revision.value=r.revision}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'配置加载失败'}finally{loading.value=false}}
onMounted(load);onBeforeUnmount(()=>controller.abort())
async function save(){if(!config.value)return;saving.value=true;error.value='';notice.value='';try{const r=await api.saveConfig(config.value,revision.value,controller.signal);config.value=r.config;revision.value=r.revision;notice.value='配置已保存，仅影响新任务。历史任务仍使用受理时配置。'}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
function addItem(){if(!config.value)return;let suffix=config.value.items.length+1;while(config.value.items.some(i=>i.itemCode===`inspection_${suffix}`))suffix++;const template=config.value.items[0];config.value.items.push(template?{...JSON.parse(JSON.stringify(template)),itemCode:`inspection_${suffix}`,name:'新检查项',enabled:true,name_aliases:[]}:{itemCode:`inspection_${suffix}`,name:'新检查项',enabled:true,handler:'stop_work_unload',name_aliases:[],materials:[]});itemIndex.value=config.value.items.length-1;materialIndex.value=-1}
function addMaterial(){if(!selected.value)return;const group=Object.keys(groups).find(g=>!selected.value!.materials.some(m=>m.material_group===g));if(!group){notice.value='该检查项已包含所有支持的清单类型。';return}const m:InspectionMaterial={material_group:group,name:groups[group],file_name_id:'',role:['threshold','design','workface_risk','coal_risk'].includes(group)?'requirement':'actual_record',cadence:'daily'};selected.value.materials.push(m);materialIndex.value=selected.value.materials.length-1}
</script>
<template>
  <section class="page-stack">
    <div class="page-intro"><div><h2>检查项配置</h2><p class="muted">从检查项进入清单，再查看单份清单的 ID 和周期。当前版本 {{ revision.slice(0,12) }}</p></div><div class="inline-actions"><button class="button secondary" @click="load">重新载入</button><button class="button primary" :disabled="saving || !config" @click="save">{{ saving?'保存中…':'保存配置' }}</button></div></div>
    <p v-if="error" class="error-banner">{{ error }}</p><p v-if="notice" class="notice-banner">{{ notice }}</p><div v-if="loading" class="loading-line">正在加载配置…</div>
    <template v-else-if="config">
      <div class="panel policy-bar"><div><strong>清单取数周期</strong><p>月报、日报和周报按任务 checkCycle 查询；未提供周期时使用当前月。年报按任务年份，半年报按该年 01、07 月。</p></div></div>
      <div class="config-layout"><div class="config-list panel"><button v-for="(item,index) in config.items" :key="index" class="config-list-item" :class="{selected:itemIndex===index}" @click="itemIndex=index;materialIndex=-1"><span class="config-code">{{ item.itemCode }}</span><strong>{{ item.name }}</strong><small>{{ item.materials.length }} 类资料 · {{ item.enabled?'已启用':'已停用' }}</small></button><button class="button secondary full" @click="addItem">新增检查项</button></div>
      <div v-if="selected" class="panel config-detail"><div class="detail-title"><div><h3>{{ selected.name }}</h3><p class="muted">{{ selected.itemCode }} · {{ selected.materials.length }} 类资料</p></div><button class="text-button danger" @click="config.items.splice(itemIndex,1);itemIndex=-1;materialIndex=-1">移除检查项</button></div><details class="edit-basic"><summary>编辑检查项基本信息</summary><div class="form-grid"><label>检查项 code<input v-model="selected.itemCode" /></label><label>检查项名称<input v-model="selected.name" /></label><label>核验逻辑<select v-model="selected.handler"><option value="stop_work_unload">停工撤人与卸压</option><option value="relief_effects">解危效果检验</option></select></label><label class="checkbox-label"><input type="checkbox" v-model="selected.enabled" />启用检查项</label></div></details><div v-if="!material" class="material-list"><button v-for="(m,index) in selected.materials" :key="index" class="material-row" :class="{selected:materialIndex===index}" @click="materialIndex=index"><span><strong>{{ m.name }}</strong><small>{{ cadence[m.cadence] || m.cadence }}</small></span><span class="row-arrow">›</span></button></div><button v-if="!material" class="text-button" @click="addMaterial">添加清单</button>
      <div v-if="material" class="material-detail"><button class="text-button" @click="materialIndex=-1">← 返回清单列表</button><div class="detail-title"><h4>{{ material.name }}</h4><button class="text-button danger" @click="selected.materials.splice(materialIndex,1);materialIndex=-1">移除此清单</button></div><div class="form-grid"><label>清单名称<input v-model="material.name" /></label><label>资料类别<select v-model="material.material_group"><option v-for="(name,key) in groups" :key="key" :value="key">{{ name }}</option></select></label><label class="span-all">OceanBase 清单 ID<input v-model="material.file_name_id" class="mono" placeholder="file_name_id" /></label><label>上报周期<select v-model="material.cadence"><option v-for="(name,key) in cadence" :key="key" :value="key">{{ name }}</option></select></label><label>证据角色<select v-model="material.role"><option value="actual_record">实际记录</option><option value="requirement">标准 / 设计要求</option><option value="statement">声明材料</option><option value="regulation">法规</option></select></label></div></div><p v-else class="detail-hint">点击清单查看和编辑具体配置。</p></div><div v-else class="panel selection-placeholder"><h3>选择一个检查项</h3><p>列表只显示检查项摘要，清单和具体字段按需展开。</p></div></div>
    </template>
  </section>
</template>
